SELECT CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, CASE WHEN cost >= 800 THEN 'high' WHEN cost >= 170 THEN 'mid' ELSE 'low' END AS cost_bucket, MAX(stock_qty) AS max_stock_qty, AVG(cost) AS avg_cost FROM products WHERE ARRAY_CONTAINS(tags, 'clearance') GROUP BY CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN cost >= 800 THEN 'high' WHEN cost >= 170 THEN 'mid' ELSE 'low' END HAVING SUM(stock_qty) > 1200
